49 #define TRACY_CL_ASSERT(p) if(!(p)) {                                                         \
50     TracyMessageL( "TRACY_CL_ASSERT failed on " TracyFile ":" TRACY_CL_TO_STRING(TracyLine) );  \
51     assert(false && "TRACY_CL_ASSERT failed");                                                \
