53 #define TRACY_CL_CHECK_ERROR(err) if(err != CL_SUCCESS) {                    \
54     std::ostringstream oss;                                                  \
55     oss << "TRACY_CL_CHECK_ERROR failed on " << TracyFile << ":" << TracyLine  \
56         << ": error code " << err;                                           \
57     auto msg = oss.str();                                                    \
58     TracyMessage(msg.data(), msg.size());                                    \
59     assert(false && "TRACY_CL_CHECK_ERROR failed");                          \
60 }
