62 namespace tracy {
63 
64     enum class EventPhase : uint8_t
65     {
66         Begin,
67         End
68     };
69 
70     struct EventInfo
71     {
72         cl_event event;
73         EventPhase phase;
74     };
75 
76     class OpenCLCtx
77     {
78     public:
79         enum { QueryCount = 64 * 1024 };
80 
81         OpenCLCtx(cl_context context, cl_device_id device)
82             : m_contextId(GetGpuCtxCounter().fetch_add(1, std::memory_order_relaxed))
83             , m_head(0)
84             , m_tail(0)
85         {
86             int64_t tcpu, tgpu;
87             TRACY_CL_ASSERT(m_contextId != 255);
88 
89             cl_int err = CL_SUCCESS;
90             cl_command_queue queue = clCreateCommandQueue(context, device, CL_QUEUE_PROFILING_ENABLE, &err);
91             TRACY_CL_CHECK_ERROR(err)
92             uint32_t dummyValue = 42;
93             cl_mem dummyBuffer = clCreateBuffer(context, CL_MEM_WRITE_ONLY, sizeof(uint32_t), nullptr, &err);
94             TRACY_CL_CHECK_ERROR(err)
95             cl_event writeBufferEvent;
96             TRACY_CL_CHECK_ERROR(clEnqueueWriteBuffer(queue, dummyBuffer, CL_FALSE, 0, sizeof(uint32_t), &dummyValue, 0, nullptr, &writeBufferEvent));
97             TRACY_CL_CHECK_ERROR(clWaitForEvents(1, &writeBufferEvent));
98 
99             tcpu = Profiler::GetTime();
100 
101             cl_int eventStatus;
102             TRACY_CL_CHECK_ERROR(clGetEventInfo(writeBufferEvent, CL_EVENT_COMMAND_EXECUTION_STATUS, sizeof(cl_int), &eventStatus, nullptr));
103             TRACY_CL_ASSERT(eventStatus == CL_COMPLETE);
104             TRACY_CL_CHECK_ERROR(clGetEventProfilingInfo(writeBufferEvent, CL_PROFILING_COMMAND_END, sizeof(cl_ulong), &tgpu, nullptr));
105             TRACY_CL_CHECK_ERROR(clReleaseEvent(writeBufferEvent));
106             TRACY_CL_CHECK_ERROR(clReleaseMemObject(dummyBuffer));
107             TRACY_CL_CHECK_ERROR(clReleaseCommandQueue(queue));
108 
109             auto item = Profiler::QueueSerial();
110             MemWrite(&item->hdr.type, QueueType::GpuNewContext);
111             MemWrite(&item->gpuNewContext.cpuTime, tcpu);
112             MemWrite(&item->gpuNewContext.gpuTime, tgpu);
113             memset(&item->gpuNewContext.thread, 0, sizeof(item->gpuNewContext.thread));
114             MemWrite(&item->gpuNewContext.period, 1.0f);
115             MemWrite(&item->gpuNewContext.type, GpuContextType::OpenCL);
116             MemWrite(&item->gpuNewContext.context, (uint8_t) m_contextId);
117             MemWrite(&item->gpuNewContext.flags, (uint8_t)0);
118 #ifdef TRACY_ON_DEMAND
119             GetProfiler().DeferItem(*item);
120 #endif
121             Profiler::QueueSerialFinish();
122         }
123 
124         void Name( const char* name, uint16_t len )
125         {
126             auto ptr = (char*)tracy_malloc( len );
127             memcpy( ptr, name, len );
128 
129             auto item = Profiler::QueueSerial();
130             MemWrite( &item->hdr.type, QueueType::GpuContextName );
131             MemWrite( &item->gpuContextNameFat.context, (uint8_t)m_contextId );
132             MemWrite( &item->gpuContextNameFat.ptr, (uint64_t)ptr );
133             MemWrite( &item->gpuContextNameFat.size, len );
134 #ifdef TRACY_ON_DEMAND
135             GetProfiler().DeferItem( *item );
136 #endif
137             Profiler::QueueSerialFinish();
138         }
139 
140         void Collect()
141         {
142             ZoneScopedC(Color::Red4);
143 
144             if (m_tail == m_head) return;
145 
146 #ifdef TRACY_ON_DEMAND
147             if (!GetProfiler().IsConnected())
148             {
149                 m_head = m_tail = 0;
150             }
151 #endif
152 
153             for (; m_tail != m_head; m_tail = (m_tail + 1) % QueryCount)
154             {
155                 EventInfo eventInfo = GetQuery(m_tail);
156                 cl_int eventStatus;
157                 cl_int err = clGetEventInfo(eventInfo.event, CL_EVENT_COMMAND_EXECUTION_STATUS, sizeof(cl_int), &eventStatus, nullptr);
158                 if (err != CL_SUCCESS)
159                 {
160                     std::ostringstream oss;
161                     oss << "clGetEventInfo falied with error code " << err << ", on event " << eventInfo.event << ", skipping...";
162                     auto msg = oss.str();
163                     TracyMessage(msg.data(), msg.size());
164                     if (eventInfo.event == nullptr) {
165                         TracyMessageL("A TracyCLZone must be paird with a TracyCLZoneSetEvent, check your code!");
166                     }
167                     assert(false && "clGetEventInfo failed, maybe a TracyCLZone is not paired with TracyCLZoneSetEvent");
168                     continue;
169                 }
170                 if (eventStatus != CL_COMPLETE) return;
171 
172                 cl_int eventInfoQuery = (eventInfo.phase == EventPhase::Begin)
173                     ? CL_PROFILING_COMMAND_START
174                     : CL_PROFILING_COMMAND_END;
175 
176                 cl_ulong eventTimeStamp = 0;
177                 err = clGetEventProfilingInfo(eventInfo.event, eventInfoQuery, sizeof(cl_ulong), &eventTimeStamp, nullptr);
178                 if (err == CL_PROFILING_INFO_NOT_AVAILABLE)
179                 {
180                     TracyMessageL("command queue is not created with CL_QUEUE_PROFILING_ENABLE flag, check your code!");
181                     assert(false && "command queue is not created with CL_QUEUE_PROFILING_ENABLE flag");
182                 }
183                 else
184                     TRACY_CL_CHECK_ERROR(err);
185 
186                 TRACY_CL_ASSERT(eventTimeStamp != 0);
187 
188                 auto item = Profiler::QueueSerial();
189                 MemWrite(&item->hdr.type, QueueType::GpuTime);
190                 MemWrite(&item->gpuTime.gpuTime, (int64_t)eventTimeStamp);
191                 MemWrite(&item->gpuTime.queryId, (uint16_t)m_tail);
192                 MemWrite(&item->gpuTime.context, m_contextId);
193                 Profiler::QueueSerialFinish();
194 
195                 if (eventInfo.phase == EventPhase::End)
196                 {
197                     // Done with the event, so release it
198                     TRACY_CL_CHECK_ERROR(clReleaseEvent(eventInfo.event));
199                 }
200             }
201         }
202 
203         tracy_force_inline uint8_t GetId() const
204         {
205             return m_contextId;
206         }
207 
208         tracy_force_inline unsigned int NextQueryId(EventInfo eventInfo)
209         {
210             const auto id = m_head;
211             m_head = (m_head + 1) % QueryCount;
212             TRACY_CL_ASSERT(m_head != m_tail);
213             m_query[id] = eventInfo;
214             return id;
215         }
216 
217         tracy_force_inline EventInfo& GetQuery(unsigned int id)
218         {
219             TRACY_CL_ASSERT(id < QueryCount);
220             return m_query[id];
221         }
222 
223     private:
224 
225         unsigned int m_contextId;
226 
227         EventInfo m_query[QueryCount];
228         unsigned int m_head; // index at which a new event should be inserted
229         unsigned int m_tail; // oldest event
230 
231     };
232 
233     class OpenCLCtxScope {
234     public:
235         tracy_force_inline OpenCLCtxScope(OpenCLCtx* ctx, const SourceLocationData* srcLoc, bool is_active)
236 #ifdef TRACY_ON_DEMAND
237             : m_active(is_active&& GetProfiler().IsConnected())
238 #else
239             : m_active(is_active)
240 #endif
241             , m_ctx(ctx)
242             , m_event(nullptr)
243         {
244             if (!m_active) return;
245 
246             m_beginQueryId = ctx->NextQueryId(EventInfo{ nullptr, EventPhase::Begin });
247 
248             auto item = Profiler::QueueSerial();
249             MemWrite(&item->hdr.type, QueueType::GpuZoneBeginSerial);
250             MemWrite(&item->gpuZoneBegin.cpuTime, Profiler::GetTime());
251             MemWrite(&item->gpuZoneBegin.srcloc, (uint64_t)srcLoc);
252             MemWrite(&item->gpuZoneBegin.thread, GetThreadHandle());
253             MemWrite(&item->gpuZoneBegin.queryId, (uint16_t)m_beginQueryId);
254             MemWrite(&item->gpuZoneBegin.context, ctx->GetId());
255             Profiler::QueueSerialFinish();
256         }
257 
258         tracy_force_inline OpenCLCtxScope(OpenCLCtx* ctx, const SourceLocationData* srcLoc, int depth, bool is_active)
259 #ifdef TRACY_ON_DEMAND
260             : m_active(is_active&& GetProfiler().IsConnected())
261 #else
262             : m_active(is_active)
263 #endif
264             , m_ctx(ctx)
265             , m_event(nullptr)
266         {
267             if (!m_active) return;
268 
269             m_beginQueryId = ctx->NextQueryId(EventInfo{ nullptr, EventPhase::Begin });
270 
271             GetProfiler().SendCallstack(depth);
272 
273             auto item = Profiler::QueueSerial();
274             MemWrite(&item->hdr.type, QueueType::GpuZoneBeginCallstackSerial);
275             MemWrite(&item->gpuZoneBegin.cpuTime, Profiler::GetTime());
276             MemWrite(&item->gpuZoneBegin.srcloc, (uint64_t)srcLoc);
277             MemWrite(&item->gpuZoneBegin.thread, GetThreadHandle());
278             MemWrite(&item->gpuZoneBegin.queryId, (uint16_t)m_beginQueryId);
279             MemWrite(&item->gpuZoneBegin.context, ctx->GetId());
280             Profiler::QueueSerialFinish();
281         }
282 
283         tracy_force_inline OpenCLCtxScope(OpenCLCtx* ctx, uint32_t line, const char* source, size_t sourceSz, const char* function, size_t functionSz, const char* name, size_t nameSz, bool is_active)
284 #ifdef TRACY_ON_DEMAND
285             : m_active(is_active && GetProfiler().IsConnected())
286 #else
287             : m_active(is_active)
288 #endif
289             , m_ctx(ctx)
290             , m_event(nullptr)
291         {
292             if (!m_active) return;
293 
294             m_beginQueryId = ctx->NextQueryId(EventInfo{ nullptr, EventPhase::Begin });
295 
296             const auto srcloc = Profiler::AllocSourceLocation( line, source, sourceSz, function, functionSz, name, nameSz );
297             auto item = Profiler::QueueSerial();
298             MemWrite( &item->hdr.type, QueueType::GpuZoneBeginAllocSrcLocSerial );
299             MemWrite(&item->gpuZoneBegin.cpuTime, Profiler::GetTime());
300             MemWrite(&item->gpuZoneBegin.srcloc, srcloc);
301             MemWrite(&item->gpuZoneBegin.thread, GetThreadHandle());
302             MemWrite(&item->gpuZoneBegin.queryId, (uint16_t)m_beginQueryId);
303             MemWrite(&item->gpuZoneBegin.context, ctx->GetId());
304             Profiler::QueueSerialFinish();
305         }
306 
307         tracy_force_inline OpenCLCtxScope(OpenCLCtx* ctx, uint32_t line, const char* source, size_t sourceSz, const char* function, size_t functionSz, const char* name, size_t nameSz, int depth, bool is_active)
308 #ifdef TRACY_ON_DEMAND
309             : m_active(is_active && GetProfiler().IsConnected())
310 #else
311             : m_active(is_active)
312 #endif
313             , m_ctx(ctx)
314             , m_event(nullptr)
315         {
316             if (!m_active) return;
317 
318             m_beginQueryId = ctx->NextQueryId(EventInfo{ nullptr, EventPhase::Begin });
319 
320             const auto srcloc = Profiler::AllocSourceLocation( line, source, sourceSz, function, functionSz, name, nameSz );
321             auto item = Profiler::QueueSerialCallstack( Callstack( depth ) );
322             MemWrite(&item->hdr.type, QueueType::GpuZoneBeginAllocSrcLocCallstackSerial);
323             MemWrite(&item->gpuZoneBegin.cpuTime, Profiler::GetTime());
324             MemWrite(&item->gpuZoneBegin.srcloc, srcloc);
325             MemWrite(&item->gpuZoneBegin.thread, GetThreadHandle());
326             MemWrite(&item->gpuZoneBegin.queryId, (uint16_t)m_beginQueryId);
327             MemWrite(&item->gpuZoneBegin.context, ctx->GetId());
328             Profiler::QueueSerialFinish();
329         }
330 
331         tracy_force_inline void SetEvent(cl_event event)
332         {
333             if (!m_active) return;
334             m_event = event;
335             TRACY_CL_CHECK_ERROR(clRetainEvent(m_event));
336             m_ctx->GetQuery(m_beginQueryId).event = m_event;
337         }
338 
339         tracy_force_inline ~OpenCLCtxScope()
340         {
341             if (!m_active) return;
342             const auto queryId = m_ctx->NextQueryId(EventInfo{ m_event, EventPhase::End });
343 
344             auto item = Profiler::QueueSerial();
345             MemWrite(&item->hdr.type, QueueType::GpuZoneEndSerial);
346             MemWrite(&item->gpuZoneEnd.cpuTime, Profiler::GetTime());
347             MemWrite(&item->gpuZoneEnd.thread, GetThreadHandle());
348             MemWrite(&item->gpuZoneEnd.queryId, (uint16_t)queryId);
349             MemWrite(&item->gpuZoneEnd.context, m_ctx->GetId());
350             Profiler::QueueSerialFinish();
351         }
352 
353         const bool m_active;
354         OpenCLCtx* m_ctx;
355         cl_event m_event;
356         unsigned int m_beginQueryId;
357     };
358 
359     static inline OpenCLCtx* CreateCLContext(cl_context context, cl_device_id device)
360     {
361         auto ctx = (OpenCLCtx*)tracy_malloc(sizeof(OpenCLCtx));
362         new (ctx) OpenCLCtx(context, device);
363         return ctx;
364     }
365 
366     static inline void DestroyCLContext(OpenCLCtx* ctx)
367     {
368         ctx->~OpenCLCtx();
369         tracy_free(ctx);
370     }
